pub fn run_adopted_embedding(
    execution: AdoptedEmbeddingExecution,
    items: Vec<EmbeddingItem>,
    input_type: EmbeddingInputType,
) -> Result<Vec<EmbeddingVector>> {
    let request = EmbeddingRequest { input_type, items };
    let response = match execution {
        AdoptedEmbeddingExecution::Real => GeminiEmbeddingAdapter::default().embed(request),
        other => GeminiEmbeddingAdapter::new(
            MockAdoptedEmbeddingClient { execution: other },
            ADOPTED_MODEL_PIN,
            ADOPTED_DIMENSIONS,
        )
        .embed(request),
    }?;
    Ok(response.vectors)

fn embed(
    &self,
    items: &[EmbeddingItem],
    model_pin: &str,
    dimensions: u32,
) -> Result<Vec<EmbeddingVector>> {
    let api_key = Self::api_key()?;
    // `:batchEmbedContents` embeds the whole batch in one request. Vertex has
    // no batch inference, so batching is client-side (07 §5.3).
    let requests = items
        .iter()
        .map(|item| {
            json!({
                "model": format!("models/{model_pin}"),
                "content": { "parts": [{ "text": item.text.clone().unwrap_or_default() }] },
                "outputDimensionality": dimensions,
            })
        })
        .collect::<Vec<_>>();
    let response: Value = ureq::post(&format!(
        "{}/v1beta/models/{model_pin}:batchEmbedContents",
        self.base_url()
    ))
    .set("x-goog-api-key", &api_key)
    .set("Content-Type", "application/json")
    .send_json(json!({ "requests": requests }))
    .map_err(http_error)?
    .into_json()
    .map_err(|err| AdapterError::ContractViolation(err.to_string()))?;
    parse_embeddings(&response, items, dimensions)

fn parse_embeddings(
    response: &Value,
    items: &[EmbeddingItem],
    dimensions: u32,
) -> Result<Vec<EmbeddingVector>> {
    let embeddings = response
        .get("embeddings")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            AdapterError::ContractViolation("embedding response missing embeddings".to_owned())
        })?;
    if embeddings.len() != items.len() {
        return Err(AdapterError::ContractViolation(
            "embedding response count does not match request".to_owned(),
        ));
    }
    items
        .iter()
        .zip(embeddings)
        .map(|(item, embedding)| {
            let vector = embedding
                .get("values")
                .and_then(Value::as_array)
                .ok_or_else(|| {
                    AdapterError::ContractViolation("embedding missing values".to_owned())
                })?
                .iter()
                .map(|value| value.as_f64().map(|value| value as f32))
                .collect::<Option<Vec<f32>>>()
                .ok_or_else(|| {
                    AdapterError::ContractViolation("embedding values must be numeric".to_owned())
                })?;
            // F7: the response vector must have exactly the requested
            // `outputDimensionality`. A wrong-width vector would otherwise be
            // persisted with the declared `dimensions` (768) but a mismatched
            // byte length, so `link_chunk_vec` silently drops it from `chunk_vec`
            // (permanent KNN exclusion) even though the chunk is billed and marked
            // done, with no self-repair path. Reject it as a contract violation so
            // the batch fails (retryable/reportable) instead of being charged.
            if vector.len() != dimensions as usize {
                return Err(AdapterError::ContractViolation(format!(
                    "embedding dimension mismatch: expected {dimensions}, got {}",
                    vector.len()
                )));
            }
            Ok(EmbeddingVector {
                id: item.id.clone(),
                vector,
            })
        })
        .collect()

/// Compute the query embedding once per search (05 §1.1). Returns `None` when no
/// adapter is configured or the query is too short to embed. A failing adapter
/// call (auth/rate) degrades to `None` → text fallback rather than erroring the
/// whole search. Query-embedding cost is not metered in the MVP (negligible; the
/// budget guardrails target bulk index enrichment).
fn compute_query_embedding(query: &str) -> Result<Option<Vec<f32>>> {
    if query.chars().count() < 2 {
        return Ok(None);
    }
    let Some(execution) = embedding_execution() else {
        return Ok(None);
    };
    // O2 regression seam: mark that the query is about to be SENT to the embedding
    // endpoint, so a test can prove `--text` never reaches this path. No-op unless
    // the env var is set (mirrors the KCS_TEST_* adapter seams).
    record_query_embed_trace(query);
    let items = vec![EmbeddingItem {
        id: "query".to_owned(),
        text: Some(query.to_owned()),
        path: None,
        mime: None,
    }];
    match run_embedding_adapter(execution, items, EmbeddingInputType::Query) {
        Ok(vectors) => Ok(vectors.into_iter().next().map(|vector| vector.vector)),
        Err(_) => Ok(None),
    }

// timeout_seconds: a per-adapter execution timeout is not threaded through
// the adapter HTTP path (it would touch every adapter's transport). Accept
// the documented default (300); reject any other value loudly rather than
// silently ignore it. (R12-2 decision: real wiring is a large change.)
if let Some(timeout) = policy.get("timeout_seconds").and_then(Value::as_i64) {
    if timeout != 300 {
        return Err(KcsError::not_implemented(
            "adapter.policy.timeout_seconds other than 300",
        ));
    }
}
